}

/// <summary>
/// 推察可能になりうる対象を表します。
/// </summary>
public interface IGuessed
{
    /// <summary>
    /// Guesserによる推測対象になる場合trueを返します。
    /// </summary>
    bool CanBeGuessDefault => true;

    /// <summary>
    /// Guesserによる推測対象になる場合trueを返します。
    /// </summary>
    bool CanBeGuess => CanBeGuessDefault && (CanBeGuessVariable?.CurrentValue ?? true);

    /// <summary>
