            {
                var acTokenAnother3 = AbstractAchievement.GenerateSimpleTriggerToken("sheriff.another3");
                GameOperatorManager.Instance?.Subscribe<MeetingEndEvent>(ev => { acTokenAnother3.Value.triggered = false; }, this);
